import React, { useState, useEffect, useContext } from 'react';
import { AuthContext } from '../context/AuthContext';
import './MascotasReportadas.css'; // Importá el CSS
import { useNavigate } from 'react-router-dom';

const MascotasReportadasPage = () => {
  const navigate = useNavigate();
  const { user } = useContext(AuthContext);
  const [mascotas, setMascotas] = useState([]);

  useEffect(() => {
    if (user?.id) {
      const fetchMascotas = async () => {
        try {
          const response = await fetch(`http://localhost:3000/api/pets?reporterId=${user.id}`);
          const data = await response.json();
          setMascotas(data);
        } catch (error) {
          console.error('Error al cargar mascotas:', error);
        }
      };

      fetchMascotas();
    }
  }, [user]);

return (
  <div className="container">
    <h1 className="tituloMascotaReportadas">Mascotas Reportadas</h1>
    <div className="mascotas-container">
      {mascotas.length > 0 ? (
        mascotas.map((mascota) => (
          <div key={mascota.id} className="mascota-card">
            <img 
              src={mascota.imageurl} 
              className="mascota-image" 
              alt={mascota.name} 
              onError={(e) => { e.target.onerror = null; e.target.src = 'ruta/por/defecto.png'; }}
            />
            <div className="mascota-info">
              <h2 className="mascota-name">{mascota.name}</h2>
              <p className="mascota-location">{mascota.location}</p>
              <button 
                className="btn-editar" 
                onClick={() => navigate(`/editar-mascota/${mascota.id}`)}
              >
                Editar
              </button>
            </div>
          </div>
        ))
      ) : (
        <p>No has reportado ninguna mascota aún.</p>
      )}
    </div>

    {/* Acá va el formulario de edición */}
    <form onSubmit={handleSubmit} className="form-editar">
      {/* Tus inputs y el mapa */}
      <label>Nombre</label>
      <input name="name" value={mascota.name} onChange={handleChange} required />

      {lat && lng && (
        <MapContainer
          center={[lat, lng]}
          zoom={13}
          style={{ height: '300px', width: '100%' }}
        >
          <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
          <LocationSelector lat={lat} lng={lng} setLat={setLat} setLng={setLng} />
        </MapContainer>
      )}

      <button type="submit">Guardar</button>
    </form>
  </div>
);
};

export default MascotasReportadasPage;
